const fs=require('node:fs/promises'),path=require('node:path'),crypto=require('node:crypto');
const spec=require('../../shared/presentmon.json');
(async()=>{const folder=path.join(__dirname,'../../assets/presentmon'),file=path.join(folder,spec.file);await fs.mkdir(folder,{recursive:true});let data;try{data=await fs.readFile(file)}catch{}if(!data||crypto.createHash('sha256').update(data).digest('hex')!==spec.sha256){const response=await fetch(spec.url);if(!response.ok)throw Error('PresentMon download failed: '+response.status);data=Buffer.from(await response.arrayBuffer());if(crypto.createHash('sha256').update(data).digest('hex')!==spec.sha256)throw Error('PresentMon SHA-256 mismatch');await fs.writeFile(file,data)}console.log('Verified official PresentMon '+spec.version+' SHA-256');})().catch(e=>{console.error(e.message);process.exitCode=1});
